do $$ declare t text; begin foreach t in array array['secondary_staff_reviews','secondary_staff_disciplinary_records','secondary_staff_payroll'] loop execute format('drop policy if exists %I on public.%I',t||'_read',t); execute format('drop policy if exists %I on public.%I',t||'_insert',t); execute format('drop policy if exists %I on public.%I',t||'_update',t); execute format('drop policy if exists %I on public.%I',t||'_delete',t); end loop; end $$;
create policy secondary_staff_reviews_read on public.secondary_staff_reviews for select to authenticated using(exists(select 1 from public.school_memberships m where m.school_id=secondary_staff_reviews.school_id and m.user_id=(select auth.uid()) and m.is_active and m.role in('owner','school_admin','headteacher')));
create policy secondary_staff_reviews_insert on public.secondary_staff_reviews for insert to authenticated with check(created_by=(select auth.uid()) and exists(select 1 from public.school_memberships m where m.school_id=secondary_staff_reviews.school_id and m.user_id=(select auth.uid()) and m.is_active and m.role in('owner','school_admin','headteacher')));
create policy secondary_staff_reviews_update on public.secondary_staff_reviews for update to authenticated using(exists(select 1 from public.school_memberships m where m.school_id=secondary_staff_reviews.school_id and m.user_id=(select auth.uid()) and m.is_active and m.role in('owner','school_admin','headteacher'))) with check(exists(select 1 from public.school_memberships m where m.school_id=secondary_staff_reviews.school_id and m.user_id=(select auth.uid()) and m.is_active and m.role in('owner','school_admin','headteacher')));
create policy secondary_staff_reviews_delete on public.secondary_staff_reviews for delete to authenticated using(exists(select 1 from public.school_memberships m where m.school_id=secondary_staff_reviews.school_id and m.user_id=(select auth.uid()) and m.is_active and m.role in('owner','school_admin','headteacher')));
